head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > invalidMessageFunc]<br/>Textarea 컴포넌트의 유효성 검증 실패 시 메시지를 동적으로 생성할 사용자 정의 함수 이름을 설정합니다.",
    "validation" : [
        "유효성 검증 실패 시 메시지를 동적으로 생성할 사용자 정의 함수 이름을 설정합니다.",
        "사용자 정의 함수에서 반환하는 문자열이 검증 실패 메시지로 표시됩니다.",
        "displaymessage=true 이고 validate() 메소드의 실행결과가 실패일때 동작합니다.",
        "invalidMessage 속성보다 우선 적용됩니다.",
        "사용자 정의 함수에서 반환된 값은 alert() 메소드로 표시됩니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실행된 컴포넌트의 렌더링 ID 를 갖는 callerId 속성을 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실행된 컴포넌트를 반환하는 getCaller() 메소드를 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실패한 항목을 문자열로 반환하는 getType() 메소드 ('mandatory', 'maxLength', 'maxByteLength', 'minLength', 'minByteLength' 값을 가짐) 메소드를 사용할 수 있습니다.",
        "사용자 정의 함수에서 this 를 통해 입력값 유효성 체크가 실패한 항목의 속성값을 반환하는 getValue() 메소드를 사용할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


// invalidMessageFunc 사용자 정의 함수
scwin.fn_msg = function () {
    let invalidCompId = this.callerId;       // invalid id
    let invalidCompObj = this.getCaller();   // invalid obj
    let invalidType = this.getType();        // invalid type
    let invalidValue = this.getValue();      // invalid value

    let msg = "";
    switch (invalidType) {
        case "mandatory" :
            msg = "Information is required.";
            break;
        case "minLength" :
            msg = "Minimum " + invalidValue + " digits are required.";
            break;
        case "minByteLength" :
            msg = "Minimum " + invalidValue + " bytes are required.";
            break;
        case "maxLength" :
            msg = "Maximum " + invalidValue + " digits are required.";
            break;
        case "maxByteLength" :
            msg = "Maximum " + invalidValue + " bytes are required.";
            break;
        default :
            msg = "Not valid.";
            break;
    }
    msg += "(id: " + invalidCompId + ", org_id: " + invalidCompObj.org_id + ")";

    return msg;
}


// target1 (mandatory 유효성 실패 후 사용자 함수 정의 메시지 출력)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}


// target2 (maxlength 유효성 실패 후 사용자 함수 정의 메시지 출력)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나다라마바");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}


// target3 (minlength 유효성 실패 후 사용자 함수 정의 메시지 출력)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("가나다");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.btn_setValue3_onclick();
    scwin.check_validate(target3);
}


// target4 (maxByteLength 유효성 실패 후 사용자 함수 정의 메시지 출력)
// WebSquare 는 한글을 EUC-KR 2바이트로 계산 → '가나다라' = 8바이트 > maxByteLength=6 (FAIL)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("가나다라");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.btn_setValue4_onclick();
    scwin.check_validate(target4);
}


// target5 (minByteLength 유효성 실패 후 사용자 함수 정의 메시지 출력)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("가");
};

scwin.btn_validate5_onclick = function (e) {
    scwin.btn_setValue5_onclick();
    scwin.check_validate(target5);
}


// target6 (invalidMessage 와 invalidMessageFunc 동시 설정 → invalidMessageFunc 우선 적용)
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("");
};

scwin.btn_validate6_onclick = function (e) {
    scwin.btn_setValue6_onclick();
    scwin.check_validate(target6);
}


// target7 (displaymessage 미설정 → invalidMessageFunc 동작하지 않음, alert 미출력)
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("");
};

scwin.btn_validate7_onclick = function (e) {
    scwin.btn_setValue7_onclick();
    scwin.check_validate(target7);
}
